//==============================================================================
/**
 * Mosaic Effect Transfer
 * Ver 0.01 2022/04/22
 * http://fweb.midi.co.jp/~mikagami/atelier/
 */
//==============================================================================

class Game_Temp {
    constructor() {
        this.clear();
    }

    clear() {
        this.fadeType2 = 0;  // Clear
    }

    mosaic() {
        this.fadeType2 = 1;  // Mosaic effect
    }

    isMosaic() {
        return this.fadeType2 === 1;  // Is Mosaic?
    }

    isActive() {
        this.fadeType2 = this.fadeType2 || 0;
        return this.fadeType2 >= 1;  // Is active?
    }
}

class Scene_Map extends Scene_Base {
    preTransfer() {
        this._mapNameWindow.close();
        if ($gameTemp.isActive()) {
            this.mosaicOut();
        } else {
            switch ($gameTemp.fadeType) {
                case 0:
                    this.fadeOut(this.fadeOutSpeed());
                    break;
                case 1:
                    this.whiteFadeOut(this.fadeOutSpeed());
                    break;
            }
        }
    }

    postTransfer() {
        if ($gameTemp.isActive()) {
            this.updateForFade();
            this.mosaicIn();
            $gameTemp.clear();
        } else {
            switch ($gameTemp.fadeType) {
                case 0:
                    this.wait(this.fadeInSpeed() / 2);
                    this.fadeIn(this.fadeInSpeed());
                    break;
                case 1:
                    this.wait(this.fadeInSpeed() / 2);
                    this.whiteFadeIn(this.fadeInSpeed());
                    break;
            }
        }
        this._mapNameWindow.open();
    }

    // Mosaic screen in
    mosaicIn(duration = 2) {
        Graphics.brightness = 255;
        const bmps = this.createMosaicBitmapArray();
        const sprite = new Sprite();
        sprite.z = 255;
        sprite.bitmap = new Bitmap(Graphics.width, Graphics.height);
        for (let i = 0; i < 16; i++) {
            sprite.bitmap.stretchBlt(sprite.bitmap.rect, bmps[15 - i], bmps[15 - i].rect);
            sprite.setColor(0, 0, 0, (16 - i) ** 2);
            for (let j = 0; j < duration; j++) {
                this.updateBasic();
            }
        }
        bmps.forEach(bmp => bmp.dispose());
        sprite.dispose();
    }

    // Mosaic screen out
    mosaicOut(duration = 2) {
        const bmps = this.createMosaicBitmapArray();
        const sprite = new Sprite();
        sprite.z = 255;
        sprite.bitmap = new Bitmap(Graphics.width, Graphics.height);
        for (let i = 0; i < 16; i++) {
            sprite.bitmap.stretchBlt(sprite.bitmap.rect, bmps[i], bmps[i].rect);
            sprite.setColor(0, 0, 0, i ** 2);
            for (let j = 0; j < duration; j++) {
                this.updateBasic();
            }
        }
        Graphics.brightness = 0;
        bmps.forEach(bmp => bmp.dispose());
        sprite.dispose();
    }

    // Create mosaic pattern
    createMosaicBitmapArray() {
        const bmp = Graphics.snapToBitmap();
        const bmps = [];
        for (let i = 0; i < 16; i++) {
            bmps[i] = new Bitmap(Graphics.width / (i * 2 + 2), Graphics.height / (i * 2 + 2));
            bmps[i].stretchBlt(bmps[i].rect, bmp, bmp.rect);
        }
        bmp.dispose();
        return bmps;
    }
}

